@props(['name', 'label', 'options' => [], 'value' => null, 'helper' => null, 'required' => false])
@php $id = $attributes->get('id', $name); $error = $errors->first($name); @endphp
<div class="grid gap-2"><label for="{{ $id }}" class="public-label">{{ $label }}@if($required)<span class="text-red-700" aria-hidden="true"> *</span><span class="sr-only"> required</span>@endif</label><select id="{{ $id }}" name="{{ $name }}" @required($required) @if($error) aria-invalid="true" aria-describedby="{{ $id }}-error" @endif {{ $attributes->except('id')->merge(['class' => 'public-control']) }}>@foreach($options as $optionValue => $optionLabel)<option value="{{ $optionValue }}" @selected(old($name, $value) == $optionValue)>{{ $optionLabel }}</option>@endforeach</select>@if($helper)<p class="public-helper">{{ $helper }}</p>@endif @if($error)<p id="{{ $id }}-error" class="public-error">{{ $error }}</p>@endif</div>
